begin;
do $test$
declare p uuid;o uuid;prod uuid;s1 uuid;s2 uuid;s3 uuid;actor uuid;campaign uuid;c uuid;item uuid;report uuid:=gen_random_uuid();job uuid;n integer;
begin
select user_id into actor from public.admins limit 1;
insert into public.periods(title,starts_on,ends_on,published) values('UPGRADE ROLLBACK TEST','2099-03-01','2099-03-15',false) returning id into p;
insert into public.offers(period_id,name,detail,sale_date,discount,image_path) values(p,'UPGRADE TEST PRODUCT','100 г','2099-03-01',20,'brand/products/2026-10/26.webp') returning id,product_id into o,prod;
insert into public.push_subscriptions(endpoint,keys,token_hash,ip_hash,notify_calendar,notify_favorites,notify_new) values('https://fcm.googleapis.com/fcm/send/UPGRADE1-'||gen_random_uuid(),'{}',repeat('a',64),'fixture',false,false,false) returning id into s1;
insert into public.push_subscriptions(endpoint,keys,token_hash,ip_hash) values('https://fcm.googleapis.com/fcm/send/UPGRADE2-'||gen_random_uuid(),'{}',repeat('b',64),'fixture') returning id into s2;
insert into public.push_subscriptions(endpoint,keys,token_hash,ip_hash,notify_favorites) values('https://fcm.googleapis.com/fcm/send/UPGRADE3-'||gen_random_uuid(),'{}',repeat('c',64),'fixture',false) returning id into s3;
perform public.push_sync_favorites(s1,array[prod],1);perform public.push_sync_favorites(s2,array[prod],1);perform public.push_sync_favorites(s3,array[prod],1);
update public.periods set published=true where id=p;
campaign:=public.push_enqueue(p,actor);
if exists(select 1 from public.push_deliveries where broadcast_id=campaign and subscription_id in(s1,s2)) then raise exception 'opt-out or duplicate generic push';end if;
if not exists(select 1 from public.push_deliveries where broadcast_id=campaign and subscription_id=s3) then raise exception 'calendar-only subscriber omitted';end if;
if exists(select 1 from public.favorite_deliveries where period_id=p and subscription_id in(s1,s3)) then raise exception 'favorites opt-out ignored';end if;
select id into job from public.favorite_deliveries where period_id=p and subscription_id=s2;
if job is null then raise exception 'favorite missing';end if;
update public.favorite_deliveries set state='sending',attempts=1 where id=job;
if public.favorite_delivery_payload(job,1) is null then raise exception 'payload missing';end if;
update public.push_subscriptions set notify_favorites=false where id=s2;
if public.favorite_delivery_payload(job,1) is not null then raise exception 'opt-out before delivery ignored';end if;
if public.push_enqueue(p,actor)<>campaign then raise exception 'broadcast not idempotent';end if;
insert into public.new_collections(title,starts_on,ends_on,published) values('ROLLBACK NEW','2099-03-01','2099-03-07',true) returning id into c;
insert into public.new_items(collection_id,name,image_path) values(c,'TEST','brand/new-arrivals/2026-11-01/01.webp') returning id into item;
campaign:=public.push_enqueue_new(c,actor);
if exists(select 1 from public.push_deliveries where broadcast_id=campaign and subscription_id=s1) then raise exception 'new opt-out ignored';end if;
if not exists(select 1 from public.push_deliveries where broadcast_id=campaign and subscription_id=s3) then raise exception 'new subscriber missing';end if;
perform public.submit_customer_feedback(report,'offer',o,'photo','Test only',repeat('f',64));
perform public.submit_customer_feedback(report,'offer',o,'photo','Test only',repeat('f',64));
if (select count(*) from public.customer_feedback where id=report)<>1 then raise exception 'duplicate feedback';end if;
for n in 1..4 loop perform public.submit_customer_feedback(gen_random_uuid(),'new',item,'link','',repeat('f',64));end loop;
begin perform public.submit_customer_feedback(gen_random_uuid(),'new',item,'link','',repeat('f',64));raise exception 'RATE_TEST_FAILED';exception when others then if sqlerrm<>'FEEDBACK_LIMIT' then raise;end if;end;
if has_table_privilege('anon','public.customer_feedback','SELECT') or has_function_privilege('anon','public.submit_customer_feedback(uuid,text,uuid,text,text,text)','EXECUTE') then raise exception 'public feedback access';end if;
if has_column_privilege('authenticated','public.customer_feedback','ip_hash','SELECT') or has_column_privilege('authenticated','public.customer_feedback','comment','UPDATE') then raise exception 'too broad admin grants';end if;
raise notice 'PASS topic filters, idempotency, deduplication, opt-out recheck, feedback rate limit and private grants';
end $test$;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000000',true);
do $$begin if exists(select id from public.customer_feedback) then raise exception 'nonadmin can see reports';end if;end$$;
rollback;
